use rk3588_boot_support::Mmio32;
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum LtssmSummary{LinkUp,TransitionSeen,IdleOrZero,Other(u32)}
pub const fn ltssm_summary(status:u32)->LtssmSummary{match status&0x30000{0x30000=>LtssmSummary::LinkUp,0x10000=>LtssmSummary::TransitionSeen,0 if status==0=>LtssmSummary::IdleOrZero,_=>LtssmSummary::Other(status)}}
pub fn program_endpoint_identity_and_width<I:Mmio32>(io:&mut I,cfg_base:u64,vendor_id:u16,device_id:u16,generation:u8,lanes:u8){io.write32(cfg_base,vendor_id as u32|((device_id as u32)<<16));if (1..=3).contains(&generation){for off in [124u64,160]{let v=io.read32(cfg_base+off);io.write32(cfg_base+off,(v&0xFFFF_FFF0)|generation as u32)}}let v124=io.read32(cfg_base+124);io.write32(cfg_base+124,(v124&0xFFFF_FC0F)|((lanes as u32)<<4));let v1808=io.read32(cfg_base+1808);io.write32(cfg_base+1808,(v1808&0xFFC0_FF7F)|(((lanes as u32)<<17).wrapping_sub(0x0001_0000)));let v2060=io.read32(cfg_base+2060);io.write32(cfg_base+2060,(v2060&0xFFFF_E0FF)|((lanes as u32)<<8));}
#[cfg(test)]mod tests{use super::*;struct M{r:[u32;4],w:[(u64,u32);6],n:usize}impl Mmio32 for M{fn read32(&mut self,a:u64)->u32{match a{124=>self.r[0],160=>self.r[1],1808=>self.r[2],2060=>self.r[3],_=>0}}fn write32(&mut self,a:u64,v:u32){self.w[self.n]=(a,v);self.n+=1;match a{124=>self.r[0]=v,160=>self.r[1]=v,1808=>self.r[2]=v,2060=>self.r[3]=v,_=>{}}}}#[test]fn config(){let mut m=M{r:[0;4],w:[(0,0);6],n:0};program_endpoint_identity_and_width(&mut m,0,0x1D87,0x356A,3,2);assert_eq!(m.w[0].1,0x356A_1D87);assert_eq!(m.r[0]&0xF,3);assert_eq!((m.r[0]>>4)&0x3F,2);assert_eq!(ltssm_summary(0x30000),LtssmSummary::LinkUp);assert_eq!(ltssm_summary(0x10000),LtssmSummary::TransitionSeen);}}
